import { UserRepository } from '../repositories/user-repository.js';

const users = new UserRepository();

export function listActiveUsers() {
  return users.findActive();
}

export function findUser(id) {
  return users.findById(id);
}

export function softDeleteUser(id, when) {
  return users.softDelete(id, when);
}

import { OrderRepository } from '../repositories/order-repository.js';
import { UserRepository } from '../repositories/user-repository.js';

const orders = new OrderRepository();
const users = new UserRepository();

export function listOrdersForUser(userId) {
  return orders.findByUser(userId);
}

export async function totalPaidCents() {
  const [paid, activeUsers] = await Promise.all([
    orders.findPaid(),
    users.findActive(),
  ]);
  const activeIds = new Set(activeUsers.map((u) => u.id));
  return paid.reduce(
    (sum, o) => (activeIds.has(o.user_id) ? sum + o.total_cents : sum),
    0,
  );
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  listActiveUsers,
  findUser,
  softDeleteUser,
} from '../src/services/user-service.js';
import { reset } from '../src/db.js';

test('listActiveUsers excludes soft-deleted users', async () => {
  const users = await listActiveUsers();
  assert.equal(users.length, 2);
  assert.ok(users.every((u) => u.deleted_at === null));
});

test('findUser returns null for an unknown id', async () => {
  const user = await findUser(999);
  assert.equal(user, null);
});

test('softDeleteUser removes a user from the active list', async () => {
  await softDeleteUser(2, '2026-02-01');
  const users = await listActiveUsers();
  assert.equal(users.length, 1);
  assert.ok(users.every((u) => u.id !== 2));
  reset();
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { listOrdersForUser, totalPaidCents } from '../src/services/order-service.js';

test('listOrdersForUser returns only that user orders', async () => {
  const orders = await listOrdersForUser(1);
  assert.equal(orders.length, 2);
  assert.ok(orders.every((o) => o.user_id === 1));
});

test('totalPaidCents excludes orders from soft-deleted users', async () => {
  const total = await totalPaidCents();
  assert.equal(total, 4200 + 9900);
});

